def count_queen_coverage(R, C, r, c):
    # R: rows (M=40), C: columns (N=60)
    # r, c: queen position (1-indexed)

    covered = set()

    # Horizontal and Vertical
    for i in range(1, R + 1):
        covered.add((i, c))
    for j in range(1, C + 1):
        covered.add((r, j))

    # Diagonal 1 (r-c constant)
    diff = r - c
    for i in range(1, R + 1):
        j = i - diff
        if 1 <= j <= C:
            covered.add((i, j))

    # Diagonal 2 (r+c constant)
    sum_rc = r + c
    for i in range(1, R + 1):
        j = sum_rc - i
        if 1 <= j <= C:
            covered.add((i, j))

    return len(covered)

R, C = 40, 60
max_coverage = 0
best_pos = (0, 0)

# Check all positions
for r in range(1, R + 1):
    for c in range(1, C + 1):
        coverage = count_queen_coverage(R, C, r, c)
        if coverage > max_coverage:
            max_coverage = coverage
            best_pos = (r, c)

print(f"Max coverage: {max_coverage}")
